logger = logging.getLogger(__name__)


def handle(event):
    try:
        payload = parse_request(event)
    except RequestParseError as e:
        return response.error(e.status_code, e.detail, event)

    try:
        result = create_architecture(payload.prompt)
    except Exception as e:
        logger.exception("Failed to analyze the architecture")
        return response.error(500, f"Could not process the architecture: {e}", event)

    return response.success(result, event)

class RequestParseError(Exception):
    """The request could not be turned into a valid input model."""

    def __init__(self, status_code, detail):
        super().__init__(detail)
        self.status_code = status_code
        self.detail = detail


def get_header(event, name):
    """Case-insensitive header lookup (API Gateway does not normalize header names)."""
    headers = event.get("headers") or {}
    name = name.lower()
    for key, value in headers.items():
        if key.lower() == name:
            return value
    return None


def parse_json_body(event):
    """Return the JSON body of an API Gateway proxy event as a Python object."""
    body = event.get("body")
    if isinstance(body, (dict, list)):
        return body  # direct invocation with an already decoded payload
    if body is None:
        body = ""
    if event.get("isBase64Encoded"):
        body = base64.b64decode(body, validate=True).decode("utf-8")
    return json.loads(body or "{}")

def parse_request(event) -> RequestPayload:
    """Decode and validate the request body.

    Raises RequestParseError with status 400 (body is not JSON) or 422 (schema mismatch).
    """
    try:
        data = parse_json_body(event)
    except (ValueError, UnicodeDecodeError) as e:
        raise RequestParseError(400, f"Invalid JSON body: {e}") from e

    try:
        return RequestPayload.model_validate(data)
    except ValidationError as e:
        raise RequestParseError(422, e.errors(include_url=False)) from e

"""Output: builds API Gateway proxy responses (JSON body and CORS headers)."""

import json

import config
from request_parser import get_header


def cors_headers(event):
    origin = get_header(event, "Origin")
    if origin and origin in config.CORS_ORIGINS:
        return {"Access-Control-Allow-Origin": origin, "Vary": "Origin"}
    return {}


def build_response(status_code, body, event=None):
    headers = {"Content-Type": "application/json", **cors_headers(event or {})}
    return {
        "statusCode": status_code,
        "headers": headers,
        "body": json.dumps(body, default=str),
    }


def success(body, event=None):
    return build_response(200, body, event)


def error(status_code, detail, event=None):
    return build_response(status_code, {"detail": detail}, event)

def ensure_rag_index():
    """Return the local path of rag_index.json, downloading it from S3 when absent.

    The download is skipped when the file already exists (warm container, or a
    local run with RAG_INDEX_PATH pointing to a prebuilt index).
    """
    index_path = config.RAG_INDEX_PATH
    if index_path.exists():
        return index_path

    if not config.RAG_S3_BUCKET:
        raise RuntimeError(
            f"RAG index not found at {index_path} and RAG_S3_BUCKET is not set"
        )

if not config.RAG_S3_BUCKET:
        raise RuntimeError(
            f"RAG index not found at {index_path} and RAG_S3_BUCKET is not set"
        )

    print(
        f"Downloading s3://{config.RAG_S3_BUCKET}/{config.RAG_S3_KEY} to {index_path}..."
    )
    index_path.parent.mkdir(parents=True, exist_ok=True)
    try:
        boto3.client("s3").download_file(
            config.RAG_S3_BUCKET, config.RAG_S3_KEY, str(index_path)
        )
    except Exception as e:
        raise RuntimeError(
            f"Could not download the RAG index from "
            f"s3://{config.RAG_S3_BUCKET}/{config.RAG_S3_KEY}: {e}"
        ) from e
    return index_path

